$id=(int)($_GET['id']??0);$u=current_user();if($u){require_cap_v10('sales.read');$cid=(int)$u['company_id'];}else{$cid=(int)($_GET['company']??0);$expires=(int)($_GET['expires']??0);$token=(string)($_GET['token']??'');$key=(string)envv('APP_KEY','');$expected=hash_hmac('sha256',$id.'|'.$expires.'|'.$cid,$key);if($cid<1||$expires<time()||$key===''||!hash_equals($expected,$token)){http_response_code(403);exit('Link expired or invalid');}}$lang=(string)($u['lang']??($_GET['lang']??'fa'));$lang=in_array($lang,['fa','en'],true)?$lang:'fa';$fa=$lang==='fa';$pdo=db();$st=$pdo->prepare("SELECT q.*,c.name customer_name,c.email customer_email,c.phone customer_phone,co.name company_name,co.logo_url,co.primary_color,co.accent_color FROM quotations q LEFT JOIN customers c ON c.id=q.customer_id JOIN companies co ON co.id=q.company_id WHERE q.id=? AND q.company_id=? AND NOT EXISTS(SELECT 1 FROM v10_record_deletions d WHERE d.company_id=q.company_id AND d.entity_type='quotations' AND d.entity_id=q.id)");$st->execute([$id,$cid]);$q=$st->fetch();if(!$q){http_response_code(404);exit('Not found');}$st=$pdo->prepare('SELECT qi.*,p.name_fa product_name_fa,p.name_en product_name_en FROM quotation_items qi LEFT JOIN v10_quote_item_products qp ON qp.company_id=qi.company_id AND qp.quotation_item_id=qi.id LEFT JOIN v10_products p ON p.id=qp.product_id WHERE qi.company_id=? AND qi.quotation_id=? ORDER BY qi.position,qi.id');$st->execute([$cid,$id]);$items=$st->fetchAll();$labels=$fa?['quotation'=>'پیشنهاد قیمت','customer'=>'مشتری','valid'=>'اعتبار تا','description'=>'شرح','qty'=>'تعداد','unit'=>'واحد','unit_price'=>'قیمت واحد','discount'=>'تخفیف','tax'=>'مالیات','line_total'=>'جمع','subtotal'=>'جمع جزء','total'=>'جمع کل','terms'=>'شرایط']:['quotation'=>'Quotation','customer'=>'Customer','valid'=>'Valid until','description'=>'Description','qty'=>'Quantity','unit'=>'Unit','unit_price'=>'Unit price','discount'=>'Discount','tax'=>'Tax','line_total'=>'Line total','subtotal'=>'Subtotal','total'=>'Total','terms'=>'Terms'];$dateText=$fa?v10_jalali($q['valid_until']):($q['valid_until']?:'—');
$logo=$q['logo_url']?'<img class="logo" src="'.e($q['logo_url']).'" alt="logo">':'';$html='<!doctype html><html lang="'.e($lang).'" dir="'.($fa?'rtl':'ltr').'"><head><meta charset="utf-8"><style>body{font-family:dejavusans,sans-serif;color:#213343;font-size:11pt}.head{border-bottom:3px solid '.e($q['primary_color']?:'#173f35').';padding-bottom:14px;margin-bottom:18px}.logo{max-height:62px;max-width:180px;float:'.($fa?'left':'right').'}.brand{font-size:22pt;font-weight:bold;color:'.e($q['primary_color']?:'#173f35').'}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #d9dfe4;padding:7px;text-align:'.($fa?'right':'left').'}th{background:#f4f6f8}.totals{margin-top:15px;margin-'.($fa?'right':'left').':auto;width:48%}.totals table{margin:0}.totals td:first-child{font-weight:bold;width:48%}.totals td:last-child{text-align:'.($fa?'left':'right').';white-space:nowrap}.totals .grand td{font-size:14pt;font-weight:bold;background:#f4f6f8}.terms{margin-top:20px;white-space:pre-wrap}</style></head><body><div class="head">'.$logo.'<div class="brand">'.e($q['company_name']).'</div><div>'.e($labels['quotation']).' · '.e($q['quote_no']).'</div></div><h2>'.e($q['title']).'</h2><p>'.e($labels['customer']).': '.e($q['customer_name']?:'—').' | '.e($labels['valid']).': '.e($dateText).'</p><table><thead><tr><th>#</th><th>'.e($labels['description']).'</th><th>'.e($labels['qty']).'</th><th>'.e($labels['unit']).'</th><th>'.e($labels['unit_price']).'</th><th>'.e($labels['discount']).'</th><th>'.e($labels['tax']).'</th><th>'.e($labels['line_total']).'</th></tr></thead><tbody>';
